# Compose the 19x13 output: 3x2 solid 5x5 panels separated by color 3.
panels = [[8,6],[9,4],[7,1]]
objects = {
  8: [[8,0,0],[8,8,0],[0,0,8]],
  6: [[0,0,6],[6,6,0],[0,0,6]],
  9: [[9,0,9],[0,9,0],[9,9,9]],
  4: [[4,4,4],[0,4,0],[0,4,4]],
  7: [[7,0,0],[7,0,7],[7,7,7]],
  1: [[1,1,0],[0,1,0],[0,1,1]],
}
out = [[3]*13 for _ in range(19)]
for br,rowcolors in enumerate(panels):
    for bc,color in enumerate(rowcolors):
        r0=1+br*6; c0=1+bc*6
        for r in range(5):
            for c in range(5):
                out[r0+r][c0+c]=color
        obj=objects[color]
        for r in range(3):
            for c in range(3):
                if obj[r][c]==0:
                    out[r0+1+r][c0+1+c]=color
                else:
                    out[r0+1+r][c0+1+c]=3
print(len(out),len(out[0]))
print('\n'.join(' '.join(map(str,row)) for row in out))

objects[7] = [[0,7,0],[7,0,7],[7,7,7]]
out = [[3]*13 for _ in range(19)]
for br,rowcolors in enumerate(panels):
    for bc,color in enumerate(rowcolors):
        r0=1+br*6; c0=1+bc*6
        for r in range(5):
            for c in range(5): out[r0+r][c0+c]=color
        for r in range(3):
            for c in range(3): out[r0+1+r][c0+1+c] = color if objects[color][r][c]==0 else 3
print('\n'.join(' '.join(map(str,row)) for row in out))
